/* eslint-disable no-console */
/**
 * Rebuilds src/assets/wordImages.ts from the word pictures on disk:
 *   assets/images/words/*.webp           (A1, A2 and the older sets)
 *   assets/images/path/<level>/words/*.webp   (one folder per level from B1 on)
 * The key is the file name without .webp (see wordKey in the generated file). A key found twice is an error.
 * Run from mobile/: node scripts/gen-word-images.js
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const dirs = [path.join(root, 'assets/images/words')];
const levelsDir = path.join(root, 'assets/images/path');
for (const level of fs.readdirSync(levelsDir).sort()) {
  const words = path.join(levelsDir, level, 'words');
  if (fs.existsSync(words) && fs.statSync(words).isDirectory()) dirs.push(words);
}

const entries = new Map();
for (const dir of dirs) {
  for (const file of fs.readdirSync(dir).filter((f) => f.endsWith('.webp'))) {
    const key = file.slice(0, -5);
    if (entries.has(key)) throw new Error(`"${key}" has two pictures: ${entries.get(key)} and ${path.join(dir, file)}`);
    entries.set(key, path.join(dir, file));
  }
}

const rel = (p) => path.relative(path.join(root, 'src/assets'), p).split(path.sep).join('/');
const quote = (k) => (/^[a-z_][a-z0-9_]*$/.test(k) ? k : `'${k}'`);
const lines = [...entries.keys()].sort().map((k) => `  ${quote(k)}: require('${rel(entries.get(k))}'),`);

const out = `/**
 * Pictures for the words of the path (3D caricature style, prompts in docs/*_kelime_gorselleri.md), keyed by the
 * word's file name: lower case, no accents, spaces as underscores ("wake up" → wake_up, "café" → cafe).
 * Generated by scripts/gen-word-images.js from assets/images/words and assets/images/path/<level>/words; do not edit
 * by hand. Words without a picture are shown as text.
 */
export const WORD_IMAGES: Record<string, number> = {
${lines.join('\n')}
};

/** File-name key of a word: "Wake up" → wake_up, "café" → cafe. */
export function wordKey(en: string): string {
  return en
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\\u0300-\\u036f]/g, '')
    .replace(/\\s+/g, '_');
}

/** The picture of a word, if it has one. */
export function wordImage(en: string): number | undefined {
  return WORD_IMAGES[wordKey(en)];
}
`;
fs.writeFileSync(path.join(root, 'src/assets/wordImages.ts'), out);
console.log(`${entries.size} word pictures → src/assets/wordImages.ts (${dirs.length} folders)`);
